$root = __DIR__;
$made = 0; $failed = [];
foreach ($FILES as $rel => $b64) {
    $dir = $root . '/' . dirname($rel);
    if (!is_dir($dir)) { @mkdir($dir, 0755, true); }
    $ok = @file_put_contents($root . '/' . $rel, base64_decode($b64));
    if ($ok !== false) { $made++; } else { $failed[] = $rel; }
}
